import sys
sys.path.insert(0, '/app')
from challenge import observed
from math import gcd
from functools import reduce

def recover(xs):
    # Use the standard determinant trick; the gcd of
    # z[i] = d[i+2]*d[i] - d[i+1]**2 is a multiple of m.
    # Use only the longest consistent prefix to be robust.
    d = [xs[i+1]-xs[i] for i in range(len(xs)-1)]
    z = [abs(d[i+2]*d[i]-d[i+1]*d[i+1]) for i in range(len(d)-2)]
    best = None
    for end in range(len(z), 0, -1):
        g = reduce(gcd, z[:end])
        if g <= max(xs):
            continue
        divs = set()
        k = 1
        while k*k <= g:
            if g % k == 0:
                divs.add(k); divs.add(g//k)
            k += 1
        for m in sorted(divs, reverse=True):
            if m <= max(xs):
                continue
            try:
                a = ((xs[2]-xs[1]) * pow((xs[1]-xs[0]) % m, -1, m)) % m
            except ValueError:
                continue
            c = (xs[1] - a*xs[0]) % m
            n_ok = 0
            for i in range(len(xs)-1):
                if (a*xs[i]+c) % m == xs[i+1]:
                    n_ok += 1
                else:
                    break
            if best is None or n_ok > best[0]:
                best = (n_ok, a, c, m)
        if best and best[0] >= end + 2:
            break
    if best is None:
        raise RuntimeError("failed")
    return best[1], best[2], best[3]

def solve():
    a, c, m = recover(observed)
    x = observed[0]
    seq = [x]
    for _ in range(len(observed) + 10):
        x = (a*x + c) % m
        seq.append(x)
    return seq[len(observed):len(observed)+10]

if __name__ == "__main__":
    print(solve())
